<?php
declare(strict_types=1);
namespace App\Controller;
use App\Core\Controller;use App\Core\Response;use App\Repository\ContrattoRepository;use App\Repository\ClienteRepository;use App\Repository\SedeRepository;use App\Repository\InterventoRepository;
final class ContrattoController extends Controller
{
 private function repo(): ContrattoRepository{return new ContrattoRepository($this->ctx->db,$this->aziendaId());}
 public function index(): Response{$records=$this->repo()->records();return $this->render('contratti/index',compact('records'));}
 public function create(): Response{$record=['cliente_id'=>$this->ctx->request->query('cliente_id')??'','sede_id'=>$this->ctx->request->query('sede_id')??'','preventivo_id'=>'','numero'=>'','titolo'=>'','servizi'=>'','data_inizio'=>date('Y-m-d'),'data_fine'=>'','frequenza'=>'mensile','totale_visite'=>12,'prezzo'=>'0','modalita_pagamento'=>'','attivita_escluse'=>'','note'=>'','stato'=>'bozza'];$quoteId=$this->ctx->request->query('preventivo_id');if($quoteId&&ctype_digit($quoteId)){$q=$this->ctx->db->fetchOne('SELECT * FROM preventivi WHERE id=:id AND azienda_id=:az AND archiviato_at IS NULL',['id'=>(int)$quoteId,'az'=>$this->aziendaId()]);if($q){$record['preventivo_id']=$q['id'];$record['cliente_id']=$q['cliente_id'];$record['sede_id']=$q['sede_id'];$record['titolo']=$q['titolo'];$record['servizi']=$q['voci']?:$q['descrizione'];$record['prezzo']=$q['imponibile'];}}return $this->form($record,null);}
 public function store(): Response
 {
  $d=$this->input();$errors=$this->validate($d);if($errors)return $this->form($d,null,$errors,422);
  $id=$this->ctx->db->transaction(function()use($d){$id=$this->repo()->create($d);$date=new \DateTimeImmutable($d['data_inizio']);$interval=$this->interval($d['frequenza']);for($n=1;$n<=(int)$d['totale_visite'];$n++){if($n>1)$date=$this->nextDate($date,$interval);$planned=$d['data_fine']&&$date->format('Y-m-d')>$d['data_fine']?null:$date->format('Y-m-d 09:00:00');$this->ctx->db->insert('visite_contratto',['azienda_id'=>$this->aziendaId(),'contratto_id'=>$id,'numero_visita'=>$n,'pianificata_il'=>$planned,'stato'=>$planned?'pianificata':'da_pianificare']);}return $id;});
  $this->ctx->audit->record('creazione','contratto',$id);return $this->redirect('/app/contratti/'.$id,'ok','Contratto creato e visite previste generate.');
 }
 public function show(int $id): Response{$contract=$this->repo()->find($id)??$this->notFound();$visite=$this->repo()->visits($id);$storici=[];foreach($visite as $v)$storici[$v['id']]=$this->repo()->history((int)$v['id']);return $this->render('contratti/show',compact('contract','visite','storici'));}
 public function reschedule(int $id,int $visitId): Response{$visit=$this->repo()->visit($id,$visitId)??$this->notFound();$new=trim((string)$this->ctx->request->post('pianificata_il',''));if($new===''||strtotime($new)===false)return $this->redirect('/app/contratti/'.$id,'error','Inserisci data e ora valide.');$new=date('Y-m-d H:i:00',strtotime($new));$reason=substr(trim((string)$this->ctx->request->post('motivo','')),0,255);$this->ctx->db->transaction(function()use($id,$visitId,$visit,$new,$reason){$this->ctx->db->insert('ripianificazioni_visite',['azienda_id'=>$this->aziendaId(),'visita_id'=>$visitId,'data_precedente'=>$visit['pianificata_il'],'data_nuova'=>$new,'motivo'=>$reason?:null,'modificato_da'=>$this->ctx->auth->id()]);$this->ctx->db->update('visite_contratto',['pianificata_il'=>$new,'stato'=>'pianificata'],['id'=>$visitId,'azienda_id'=>$this->aziendaId()]);$event=$this->ctx->db->fetchValue('SELECT id FROM eventi_calendario WHERE azienda_id=:az AND contratto_id=:c AND visita_contratto_id=:v AND archiviato_at IS NULL',['az'=>$this->aziendaId(),'c'=>$id,'v'=>$visitId]);if($event)$this->ctx->db->update('eventi_calendario',['inizio'=>$new],['id'=>(int)$event,'azienda_id'=>$this->aziendaId()]);else $this->ctx->db->insert('eventi_calendario',['azienda_id'=>$this->aziendaId(),'tipo'=>'intervento','titolo'=>'Visita contratto #'.$id.' · '.$visit['numero_visita'],'inizio'=>$new,'contratto_id'=>$id,'visita_contratto_id'=>$visitId,'creato_da'=>$this->ctx->auth->id()]);});$this->ctx->audit->record('ripianificazione','visita_contratto',$visitId,['motivo'=>$reason]);return $this->redirect('/app/contratti/'.$id,'ok','Visita riprogrammata; la modifica è stata registrata nello storico.');}
 public function createIntervention(int $id,int $visitId): Response{$visit=$this->repo()->visit($id,$visitId)??$this->notFound();if($visit['intervento_id'])return $this->redirect('/app/interventi/'.$visit['intervento_id'],'info','Intervento già collegato.');if(!$visit['sede_id'])return $this->redirect('/app/contratti/'.$id,'error','Aggiungi una sede al contratto prima di creare le visite operative.');$interventionId=$this->ctx->db->transaction(function()use($id,$visitId,$visit){$iid=$this->ctx->db->insert('interventi',['azienda_id'=>$this->aziendaId(),'cliente_id'=>$visit['cliente_id'],'sede_id'=>$visit['sede_id'],'contratto_id'=>$id,'visita_contratto_id'=>$visitId,'tipo_servizio'=>'altro','descrizione'=>$visit['servizi'],'pianificato_il'=>$visit['pianificata_il'],'stato'=>$visit['pianificata_il']?'pianificato':'da_pianificare']);$this->ctx->db->update('visite_contratto',['intervento_id'=>$iid,'stato'=>$visit['pianificata_il']?'pianificata':'da_pianificare'],['id'=>$visitId,'azienda_id'=>$this->aziendaId()]);if($visit['pianificata_il'])$this->ctx->db->insert('eventi_calendario',['azienda_id'=>$this->aziendaId(),'tipo'=>'intervento','titolo'=>'Visita contratto #'.$id.' · '.$visit['numero_visita'],'inizio'=>$visit['pianificata_il'],'intervento_id'=>$iid,'contratto_id'=>$id,'visita_contratto_id'=>$visitId,'creato_da'=>$this->ctx->auth->id()]);return $iid;});$this->ctx->audit->record('creazione_visita','contratto',$id,['intervento_id'=>$interventionId]);return $this->redirect('/app/interventi/'.$interventionId,'ok','Intervento creato dalla visita del contratto.');}
 private function input(): array{return $this->ctx->request->only(['cliente_id','sede_id','preventivo_id','numero','titolo','servizi','data_inizio','data_fine','frequenza','totale_visite','prezzo','modalita_pagamento','attivita_escluse','note','stato']);}
 private function validate(array $d): array{$e=[];foreach(['cliente_id','sede_id','numero','titolo','data_inizio','frequenza','totale_visite','stato'] as $f)if($d[$f]==='')$e[$f]='Campo obbligatorio.';if($d['cliente_id']!==''&&!ctype_digit($d['cliente_id']))$e['cliente_id']='Cliente non valido.';if($d['cliente_id']!==''&&!(new ClienteRepository($this->ctx->db,$this->aziendaId()))->find((int)$d['cliente_id']))$e['cliente_id']='Cliente non valido.';if($d['sede_id']!==''&&$d['cliente_id']!==''){$s=(new SedeRepository($this->ctx->db,$this->aziendaId()))->find((int)$d['sede_id']);if(!$s||(int)$s['cliente_id']!==(int)$d['cliente_id'])$e['sede_id']='La sede deve appartenere al cliente selezionato.';}if($d['preventivo_id']!==''&&(!ctype_digit($d['preventivo_id'])||!$this->ctx->db->fetchOne('SELECT id FROM preventivi WHERE id=:id AND azienda_id=:az AND cliente_id=:cliente AND archiviato_at IS NULL',['id'=>(int)$d['preventivo_id'],'az'=>$this->aziendaId(),'cliente'=>(int)$d['cliente_id']])))$e['preventivo_id']='Il preventivo deve appartenere al cliente selezionato.';if(!in_array($d['frequenza'],['settimanale','quindicinale','mensile','bimestrale','trimestrale','semestrale','annuale'],true))$e['frequenza']='Frequenza non valida.';if(!ctype_digit($d['totale_visite'])||(int)$d['totale_visite']<1||(int)$d['totale_visite']>240)$e['totale_visite']='Indica un numero da 1 a 240.';if($d['data_inizio']!==''&&!\DateTimeImmutable::createFromFormat('Y-m-d',$d['data_inizio']))$e['data_inizio']='Data non valida.';if($d['data_fine']!==''&&!\DateTimeImmutable::createFromFormat('Y-m-d',$d['data_fine']))$e['data_fine']='Data non valida.';if(!is_numeric($d['prezzo'])||(float)$d['prezzo']<0)$e['prezzo']='Inserisci un prezzo valido.';if(!in_array($d['stato'],['bozza','da_accettare','attivo','sospeso','scaduto','cessato'],true))$e['stato']='Stato non valido.';return $e;}
 private function form(array $contract,?int $id,array $errors=[],int $status=200): Response{$clienti=(new ClienteRepository($this->ctx->db,$this->aziendaId()))->all('1=1',[],'denominazione');$sedi=(new SedeRepository($this->ctx->db,$this->aziendaId()))->withCliente();return $this->render('contratti/form',compact('contract','clienti','sedi','errors','id'),'layout',$status);}
 private function interval(string $freq): array{return match($freq){'settimanale'=>['days'=>7],'quindicinale'=>['days'=>14],'mensile'=>['months'=>1],'bimestrale'=>['months'=>2],'trimestrale'=>['months'=>3],'semestrale'=>['months'=>6],default=>['months'=>12]};}
 private function nextDate(\DateTimeImmutable $date,array $interval): \DateTimeImmutable{if(isset($interval['days']))return $date->modify('+'.$interval['days'].' days');$day=(int)$date->format('d');$next=$date->modify('first day of +'.$interval['months'].' months');return $next->setDate((int)$next->format('Y'),(int)$next->format('m'),min($day,(int)$next->format('t')));}
}
